function [i, g] = quad_currents(s, p, g)
%QUAD_CURRENTS  The four currents (shares of the full-Sun current) for the Sun s (head frame, unit).
%   s: real[1][3] (passed a plain number)
%   p: SunHead (passed rec)
%   g: inout stream (passed a random stream, as six numbers)
%   returns i: real[1][4] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    i = zeros(4, 1);
    i = [0; 0; 0; 0];
    if (~(s(3) <= 0))
        dx = ((p.h * s(1)) / s(3));
        dy = ((p.h * s(2)) / s(3));
        xp = asils.models.sunquad.quad_overlap(0, Inf, (dx - (p.a / 2)), (dx + (p.a / 2)));
        xm = asils.models.sunquad.quad_overlap((-(Inf)), 0, (dx - (p.a / 2)), (dx + (p.a / 2)));
        yp = asils.models.sunquad.quad_overlap(0, Inf, (dy - (p.a / 2)), (dy + (p.a / 2)));
        ym = asils.models.sunquad.quad_overlap((-(Inf)), 0, (dy - (p.a / 2)), (dy + (p.a / 2)));
        a2 = (p.a * p.a);
        i = [(s(3) * ((xp * yp) / a2)); (s(3) * ((xm * yp) / a2)); (s(3) * ((xm * ym) / a2)); (s(3) * ((xp * ym) / a2))];
        for k = (0):((4) - 1)
            [t__253, t__254] = asils.pc.stream_normal(g);
            z = t__253;
            g = t__254;
            i((k) + 1) = (i((k) + 1) + (p.noise * z));
        end
    end
end
